use super::*;
use crate::txn::days_between;

pub fn promo_state_of(account: &str, as_of: &str, promo_ends: &[(String, String)], urgency_days: i64) -> PromoState {
    let Some(ends) = promo_end_for(account, promo_ends) else { return PromoState::None };
    // An END DATE ALREADY PASSED is not a promotion — it is an ordinary balance, and treating it as
    // one that expired long ago would keep it pinned to the front of the list forever.
    if ends <= as_of {
        return PromoState::None;
    }
    if days_between(as_of, ends) <= urgency_days { PromoState::Expiring } else { PromoState::Live }
}
